describe("Invoice cancellation", () => {
  it("should transition to CANCELLED from any active state", () => {
    const dueDate = new Date("2024-01-15");
    const activeStates: DunningStatus[] = [
      "ISSUED",
      "DUE_SOON",
      "OVERDUE",
      "GRACE",
