): number {
  const holidays = createHolidaySet(config.holidays);
  const elapsed = getBusinessDaysDifference(state.stateEnteredAt, now, holidays);
  const pausedElapsed = state.pausedElapsed ?? 0;
  return elapsed + pausedElapsed;
