  state: DunningState,
  newStatus: DunningStatus,
  now: Date,
  _config: Required<DunningConfig>
): ProcessResult {
  const actions = getTransitionActions(newStatus);

  const newState: DunningState = {
    ...state,
    status: newStatus,
